class Solution {
public:
    int minimumPossibleSum(long long n, int target) {
        const long long MOD = 1e9 + 7;
        long long k = min(n, (long long)target / 2);
        long long m = n - k;
        long long s1 = k % MOD * ((k + 1) % MOD) % MOD * 500000004 % MOD;
        long long s2 = m % MOD * ((2LL * target + m - 1) % MOD) % MOD * 500000004 % MOD;
        return (s1 + s2) % MOD;
    }
};

