var minimumPossibleSum = function(n, target) {
    const MOD = 1e9 + 7n;
    let k = BigInt(Math.min(Number(n), Math.floor(target / 2)));
    let m = BigInt(n) - k;
    let t = BigInt(target);
    let s1 = k * (k + 1n) / 2n % MOD;
    let s2 = m * (2n * t + m - 1n) / 2n % MOD;
    return Number((s1 + s2) % MOD);
};

