class Solution {
public:
    int minimumPossibleSum(int n, int target) {
        const long long MOD = 1e9 + 7;
        unordered_set<int> used;
        long long ans = 0;
        for (int v = 1; (int)used.size() < n; v++) {
            if (!used.count(target - v) || target - v == v) {
                used.insert(v);
                ans = (ans + v) % MOD;
            }
        }
        return ans;
    }
};

